from scipy.optimize import least_squares
def load(f):
    d=pd.read_csv(f); return {k:d[k].values for k in d.columns}
files=['train/A_vref_op1.csv','train/A_vref_op3.csv','train/A_amb_op1.csv','train/A_amb_op2.csv']
D={f:load(f) for f in files}
def simQ(p,d):
    Tm,Tq,Kq,Kd,Kv,Kqv=p
    t=d['time_s'];V=d['voltage_pu'];S=d['voltage_setpoint_pu']
    V0=V[0];S0=S[0];Q0=d['reactive_power_pu'][0]
    dt=t[1]-t[0];n=len(t)
    xv=V0;xq=Q0;Q=np.empty(n)
    for i in range(n):
        Q[i]=xq+Kd*(S[i]-S0)-Kv*(V[i]-V0)
        dxq=(Q0+Kq*(S[i]-xv)-(xq-Q0)*0-xq)/Tq  # placeholder
        dxq=(Q0+Kq*(S[i]-xv)-xq)/Tq
        dxv=(V[i]-xv)/Tm
        xq+=dt*dxq; xv+=dt*dxv
    return Q
def res(p,fl):
    return np.concatenate([simQ(p,D[f])-D[f]['reactive_power_pu'] for f in fl])
for start in [[0.02,0.2,5,0.5,0.0,0],[0.05,0.5,2,0.0,0.5,0.0],[0.01,0.1,20,0.3,0.5,0.0]]:
