def design(f,na,nb,use):
    d=load(f); dec=10
    V=d['voltage_pu'][::dec]-1; th=d['bus_angle_rad'][::dec]; S=d['voltage_setpoint_pu'][::dec]-1
    P=d['active_power_pu'][::dec];Q=d['reactive_power_pu'][::dec]
    n=len(V)
    sig={'S':S,'V':V,'th':th,'w':np.r_[0,np.diff(th)]}
    rows={'P':[],'Q':[]};tg={'P':[],'Q':[]}
    for key,y in [('P',P-P[0]),('Q',Q-Q[0])]:
        R=[];T=[]
        for k in range(nb,n):
            r=[y[k-i] for i in range(1,na+1)]
            for s in use:
                r+= [sig[s][k-i] for i in range(0,nb)]
            R.append(r);T.append(y[k])
        rows[key]=np.array(R);tg[key]=np.array(T)
    return rows,tg
for use in [['S','V'],['S','V','w'],['S','V','th'],['S','V','th','w']]:
    for na in [2,3]:
        out=[]
        for key in 'PQ':
            Xs=[];Ys=[]
            for f in files:
                r,t=design(f,na,4,use); Xs.append(r[key]);Ys.append(t[key])
            X=np.vstack(Xs);y=np.concatenate(Ys)
            c,*_=np.linalg.lstsq(X,y,rcond=None)
            out.append(np.sqrt(np.mean((X@c-y)**2)))
        print(use,na,np.round(out,6))

